use vstd::prelude::*;

verus! {

spec fn is_ascii_digit_spec(c: char) -> bool {
    '0' <= c && c <= '9'
}

spec fn all_digits_spec(s: Seq<char>) -> bool {
    forall|i: int| 0 <= i && i < s.len() ==> is_ascii_digit_spec(s.index(i))
}

fn is_ascii_digit(c: char) -> bool {
    // Check if the character is between '0' and '9' inclusive
    ensures
        is_ascii_digit(c) == is_ascii_digit_spec(c),
    {
        c >= '0' && c <= '9'
    }
}

fn all_digits(s: String) -> bool {
    // Check that every character in the string is an ASCII digit.
    // According to the problem, the empty string should return true.
    ensures
        all_digits(s) == all_digits_spec(Seq::from_iter(s.chars())),
    {
        let chars_seq = Seq::from_iter(s.chars());
        let mut i: usize = 0;
        while i < s.len()
            invariant
                i <= s.len(),
                // The prefix up to i of chars are all digits
                (forall|j: int| 0 <= j && j < i as int ==> is_ascii_digit_spec(chars_seq.index(j))),
            decreases s.len() - i,
        {
            let c = s.chars().nth(i).unwrap();
            if !is_ascii_digit(c) {
                return false;
            }
            i += 1;
        }
        true
    }
}
}

